  // --- Instance state ---

  Map<String, String>? _configProps;
  bool _configPropsLoaded = false;
  Map<String, String>? _envProps;
  bool _envPropsLoaded = false;
  String? _projectRoot;

  /// Resolves a property key through the full chain.
