+        () async {
+      PropertyReader.testEnvironment['DEFAULT_TRACKER'] = 'ado';
+      final result =
+          await _dispatchTool(['tracker_get_ticket', '{"key": "4242"}']);
+      expect(result['error'], contains('ADO not configured'),
+          reason: 'DEFAULT_TRACKER=ado picks the ado carrier');
+    });
+  });
+}
