+      propertyReader: PropertyReader(basePath: _tmp.path),
+      isTty: () => false,
+    );
+  });
+
+  tearDown(() {
+    PropertyReader.clearOverrides();
+    if (_tmp.existsSync()) _tmp.deleteSync(recursive: true);
+  });
+
+  _testPropertyChainRouting();
+  _testFileTierRouting();
+}
+
