  /// Key: `JIRA_TRANSFORM_CUSTOM_FIELDS_TO_NAMES`, default: true.
  bool isJiraTransformCustomFieldsToNames() {
    final v = getValueWithDefault(
      'JIRA_TRANSFORM_CUSTOM_FIELDS_TO_NAMES',
